/**
 * Derivation + cross-check of one declension paradigm from the oracles.
 *
 * Rule: a form is accepted into a cell only when at least two independent source families attest it
 * (vidyut = ashtadhyayi.com tables generated by vidyut-prakriya; huet = Sanskrit Heritage tables;
 * cologne = csl-inflect hand tables; kale = learnsanskrit.org tables after M. R. Kale).
 * Anything attested by a single family is reported and left out unless the spec accepts it with a reason.
 */
import { devaToSlp1, slp1ToDeva } from '../../../../src/sanskrit/translit.ts';
import type { ShabdaSpec } from '../shabda-spec.ts';
import { type Cells, declineWithKaleEndings, loadAshtadhyayi, loadHuet, loadKaleDirect, loadPydecl } from './oracles.ts';
import { canon, devoicedFinal, natvaFrom } from './slp.ts';

export type Family = 'vidyut' | 'huet' | 'cologne' | 'kale';

export interface SourceUse {
  family: Family;
  /** provenance tag recorded in the pack, e.g. `oracle:ashtadhyayi-com(vidyut-prakriya)#@rAma1` */
  tag: string;
  cells: Cells;
}

export interface Leftover {
  cell: string; // `${vibhakti}.${vacana}`
  form: string; // SLP1
  families: Family[];
  /**
   * sandhi-variant: voiced-final doublet of an accepted form (रामाद् ~ रामात्) — not a separate answer.
   * huet-extra: only in the Heritage table (which merges homonymous and Vedic stems).
   * kale-endings-extra: artefact of applying Kale's generic ending table (lists endings of several sub-classes).
   * not-in-vidyut: attested by other families but not generated by the Pāṇinian engine (e.g. Vedic सखाया).
   * no-vocative: sambodhana of pronouns / numerals is deliberately left empty.
   * single-source: one family only — left out.
   * accepted-by-rule / accepted-by-spec: one family only, accepted for a stated grammatical reason (listed in REVIEW.md).
   */
  verdict: 'sandhi-variant' | 'huet-extra' | 'kale-endings-extra' | 'not-in-vidyut' | 'no-vocative' | 'single-source' | 'accepted-by-rule' | 'accepted-by-spec';
  why?: string;
}

export interface Derived {
  spec: ShabdaSpec;
  stemSlp: string;
  sources: SourceUse[];
  /** accepted forms per cell, SLP1, display form first */
  cells: string[][];
  leftovers: Leftover[];
  /** cells where sources attest forms but nothing reached two families */
  holes: string[];
}

const LINGA: Record<string, string> = { m: 'P', f: 'S', n: 'N' };

let ashtByWord: Map<string, string[]> | undefined;
function ashtIdsFor(word: string, linga: string): string[] {
  if (!ashtByWord) {
    ashtByWord = new Map();
    for (const e of loadAshtadhyayi().values()) {
      const k = `${e.word} ${e.linga}`;
      const list = ashtByWord.get(k);
      if (list) list.push(e.urlid);
      else ashtByWord.set(k, [e.urlid]);
    }
  }
  return ashtByWord.get(`${word} ${linga}`) ?? [];
}

const IRREGULAR_NO_ENDINGS = new Set(['saKi', 'pati', 'strI', 'SrI', 'lakzmI', 'BU', 'akzi', 'daDi', 'pitf', 'BrAtf', 'mAtf', 'svasf', 'duhitf', 'go', 'nO', 'yuvan', 'Svan', 'ahan', 'paTin', 'ap']);

function kaleEndingType(stem: string, spec: ShabdaSpec): string | undefined {
  if (spec.ke === '-') return undefined;
  if (spec.ke) return spec.ke;
  if (spec.kind === 'pronoun' || spec.kind === 'numeral') return undefined;
  if (IRREGULAR_NO_ENDINGS.has(stem)) return undefined;
  if (/(mahat|dadat|sat|gacCat|kurvat)$/.test(stem)) return undefined;
  for (const t of ['mat', 'vat', 'yas', 'an', 'in', 'as', 'is', 'us']) {
    if (stem.endsWith(t)) {
      if ((t === 'as' || t === 'is' || t === 'us') && spec.gender !== 'n') return undefined;
      return t;
    }
  }
  const last = stem.slice(-1);
  if ('aAiIuUf'.includes(last)) return last;
  return undefined;
}

/** Declines by substituting the stem into a model paradigm of the same class (ṇatva re-derived for the new stem). */
function byModel(modelCells: Cells, modelStem: string, stem: string): Cells {
  // strip the stem-final vowel so that vowel-changing endings substitute correctly (deva → dev-, latA → lat-)
  const cut = (x: string): string => x.replace(/[aAiIuUfF]$/, '');
  const mBase = cut(modelStem);
  const base = cut(stem);
  return modelCells.map((cell) =>
    cell.map((f) => {
      if (!f.startsWith(mBase)) throw new Error(`model form ${f} does not start with ${mBase}`);
      const suffix = f.slice(mBase.length).replace(/R/g, 'n');
      return natvaFrom(base + suffix, base.length);
    }),
  );
}

export function resolveSources(spec: ShabdaSpec): SourceUse[] {
  const stem = devaToSlp1(spec.stem);
  const out: SourceUse[] = [];
  const A = loadAshtadhyayi();
  // --- vidyut family
  if (spec.model) {
    const m = A.get(spec.model.urlid);
    if (!m) throw new Error(`${spec.id}: model ${spec.model.urlid} not found`);
    out.push({ family: 'vidyut', tag: `model:ashtadhyayi-com(vidyut-prakriya)#${spec.model.urlid}`, cells: byModel(m.cells, spec.model.stem, stem) });
  } else {
    const ids = spec.a ? [spec.a] : ashtIdsFor(spec.stem, LINGA[spec.gender] ?? 'P');
    if (ids.length > 1) throw new Error(`${spec.id}: ambiguous ashtadhyayi.com entries ${ids.join(', ')} — set spec.a`);
    const id = ids[0];
    if (id) {
      const e = A.get(id);
      if (!e) throw new Error(`${spec.id}: ${id} not found`);
      out.push({ family: 'vidyut', tag: `oracle:ashtadhyayi-com(vidyut-prakriya)#${id}`, cells: e.cells });
    }
  }
  // --- huet family
  if (spec.h !== '-') {
    const key = spec.h ?? `${stem} ${spec.genderless && spec.kind === 'pronoun' ? 'd' : spec.gender}`;
    const h = loadHuet().get(key);
    if (h) out.push({ family: 'huet', tag: `oracle:heritage-huet(csl-inflect)#${key}`, cells: h });
    else if (spec.h) throw new Error(`${spec.id}: Huet key ${spec.h} not found`);
  }
  // --- cologne family
  const C = loadPydecl();
  const cKeys = spec.c ? [spec.c] : ['pron', 'card', 'irr'].map((m) => `${stem},${spec.gender}_${m}`);
  for (const key of cKeys) {
    const c = C.get(key);
    if (c) out.push({ family: 'cologne', tag: `oracle:csl-inflect-pydecl#${key}`, cells: c });
    else if (spec.c) throw new Error(`${spec.id}: pydecl key ${spec.c} not found`);
  }
  // --- kale family
  const K = loadKaleDirect();
  const kKeys = spec.k ? [spec.k] : [`${stem} ${spec.gender}`, `${stem} none`];
  let kaleDirect = false;
  for (const key of kKeys) {
    if (spec.k === '-') break;
    const k = K.get(key);
    if (k) {
      out.push({ family: 'kale', tag: `oracle:learnsanskrit-kale#${key}`, cells: k });
      kaleDirect = true;
      break;
    }
  }
  if (!kaleDirect) {
    const t = kaleEndingType(stem, spec);
    if (t) {
      const cells = declineWithKaleEndings(stem, t, spec.gender);
      if (cells) out.push({ family: 'kale', tag: `oracle:learnsanskrit-kale-endings#${t}-${spec.gender}`, cells });
      else if (spec.ke) throw new Error(`${spec.id}: Kale ending table ${t} ${spec.gender} not applicable`);
    }
  }
  return out;
}

export function cellName(i: number): string {
  return `${Math.floor(i / 3) + 1}.${(i % 3) + 1}`;
}

/** 8.3.36 वा शरि: a visarga before a sibilant may optionally assimilate to it (मनःसु ~ मनस्सु, आशीःषु ~ आशीष्षु). */
function visargaSibilantBase(f: string): string | undefined {
  if (f.endsWith('ssu')) return f.slice(0, -3) + 'Hsu';
  if (f.endsWith('zzu')) return f.slice(0, -3) + 'Hzu';
  return undefined;
}

const ENCLITICS = new Set(['mA', 'me', 'nO', 'naH', 'tvA', 'te', 'vAm', 'vaH']);

function orderCell(forms: string[], i: number, spec: ShabdaSpec, stem: string, nomSg: string | undefined): string[] {
  const name = cellName(i);
  const first = spec.first?.[name] ? canon(devaToSlp1(spec.first[name]!)) : undefined;
  if (first && !forms.includes(first)) throw new Error(`${spec.id} ${name}: preferred form ${first} is not among the accepted forms ${forms.join('/')}`);
  const vib = Math.floor(i / 3) + 1;
  const vac = (i % 3) + 1;
  const score = (f: string): number => {
    let sc = 0;
    if (f === first) sc -= 100;
    if (spec.kind === 'pronoun' && (ENCLITICS.has(f) || /^en/.test(f))) sc += 10;
    if (visargaSibilantBase(f)) sc += 5;
    if (spec.gender === 'f' && /[iu]$/.test(stem) && /(yE|yAH|yAm|vE|vAH|vAm)$/.test(f)) sc -= 1;
    if (stem === 'SrI' || stem === 'BU') {
      if (/(E|AH)$/.test(f)) sc -= 1;
      if (vib === 6 && vac === 3 && /[nR]Am$/.test(f)) sc -= 1;
      if (vib === 7 && vac === 1 && /Am$/.test(f)) sc -= 1;
    }
    if (stem === 'strI' && f.includes('iy')) sc -= 1;
    if (/an$/.test(stem) || stem === 'akzi' || stem === 'daDi') sc += f.length * 0.01;
    if (vib === 8 && vac === 1 && nomSg && f === nomSg) sc -= 0.5;
    return sc;
  };
  return forms
    .map((f, k) => ({ f, k, sc: score(f) }))
    .sort((a, b) => a.sc - b.sc || a.k - b.k)
    .map((x) => x.f);
}

export function derive(spec: ShabdaSpec): Derived {
  const stemSlp = devaToSlp1(spec.stem);
  const sources = resolveSources(spec);
  const hasVidyut = sources.some((s) => s.family === 'vidyut');
  const kaleEndingsOnly = sources.filter((s) => s.family === 'kale').every((s) => s.tag.includes('kale-endings'));
  const noVocative = spec.kind === 'pronoun' || spec.kind === 'numeral';
  const cells: string[][] = [];
  const leftovers: Leftover[] = [];
  const holes: string[] = [];
  for (let i = 0; i < 24; i++) {
    const name = cellName(i);
    const votes = new Map<string, Set<Family>>();
    for (const src of sources) {
      for (const f of src.cells[i] ?? []) {
        const set = votes.get(f);
        if (set) set.add(src.family);
        else votes.set(f, new Set([src.family]));
      }
    }
    if (noVocative && i >= 21) {
      for (const [f, fams] of votes) leftovers.push({ cell: name, form: f, families: [...fams], verdict: 'no-vocative' });
      cells.push([]);
      continue;
    }
    const accepted: string[] = [];
    for (const [f, fams] of votes) if (fams.size >= 2 && (!hasVidyut || fams.has('vidyut'))) accepted.push(f);
    // rule-based acceptance: 8.3.36
    for (const [f, fams] of votes) {
      const base = visargaSibilantBase(f);
      if (base && !accepted.includes(f) && accepted.includes(base) && fams.has('vidyut')) {
        accepted.push(f);
        leftovers.push({ cell: name, form: f, families: [...fams], verdict: 'accepted-by-rule', why: '8.3.36 वा शरि (optional assimilation of visarga before स/ष)' });
      }
    }
    const specAccept = spec.accept?.[name];
    for (const f of (specAccept?.forms ?? []).map((d) => canon(devaToSlp1(d)))) {
      const fams = votes.get(f);
      if (!fams) throw new Error(`${spec.id} ${name}: spec accepts ${f} but no source attests it`);
      if (accepted.includes(f)) throw new Error(`${spec.id} ${name}: spec.accept for ${f} is unnecessary (already confirmed by two families)`);
      accepted.push(f);
      leftovers.push({ cell: name, form: f, families: [...fams], verdict: 'accepted-by-spec', why: specAccept?.why });
    }
    for (const [f, fams] of votes) {
      if (accepted.includes(f)) continue;
      const dev = devoicedFinal(f);
      let verdict: Leftover['verdict'] = 'single-source';
      if (dev && accepted.includes(dev)) verdict = 'sandhi-variant';
      else if (fams.size === 1 && fams.has('huet')) verdict = 'huet-extra';
      else if (fams.size === 1 && fams.has('kale') && kaleEndingsOnly) verdict = 'kale-endings-extra';
      else if (fams.size >= 2) verdict = 'not-in-vidyut';
      leftovers.push({ cell: name, form: f, families: [...fams], verdict });
    }
    if (accepted.length === 0 && votes.size > 0) holes.push(name);
    cells.push(accepted);
  }
  const nomSg = cells[0]?.[0];
  const ordered = cells.map((c, i) => (c.length > 1 ? orderCell(c, i, spec, stemSlp, nomSg) : c));
  return { spec, stemSlp, sources, cells: ordered, leftovers, holes };
}

export function toDeva(slp: string): string {
  return slp1ToDeva(slp).normalize('NFC');
}
